def find_specific_sequence(data_string):
    """
    Finds the sequence of digits that appears in the provided string, 
    starting from the first occurrence of '1' and ending at the last occurrence of '2'.
    
    Args:
        data_string (str): The string containing digits.
        
    Returns:
        str: The extracted sequence, or an empty string if the pattern is not found.
    """
    
    # 1. Find the index of the first '1'
    start_index = data_string.find('1')
    
    if start_index == -1:
        return ""  # No '1' found, so the sequence cannot start.
    
    # 2. Find the index of the last '2'
    end_index = data_string.rfind('2')
    
    if end_index == -1:
        return ""  # No '2' found, so the sequence cannot end.
    
    # 3. Determine the actual start and end points for slicing
    # The sequence must start at the first '1' (start_index)
    # The sequence must end at the last '2' (end_index)
    
    # We need to ensure that the start index is before or at the end index.
    if start_index > end_index:
        return ""
    
    # Python slicing [start:end+1] includes the character at end_index.
    # Since we want to include the character at end_index, the slice end should be end_index + 1.
    result = data_string[start_index : end_index + 1]
    
    return result

